import { MakeLogicType, afterMount, connect, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { type TraceSample, fetchTraceSamples } from './traceSamples'

export interface ReportCitationSamplesLogicProps {
    runId: string
    traceIds: string[]
    /** Bounds for the people read, around the report's period. */
    earliest: string
    latest: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportCitationSamplesLogicValues {
    currentTeamId: number | null // teamLogic
    samples: Record<string, TraceSample> | null
    samplesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportCitationSamplesLogicActions {
    loadSamples: () => any
    loadSamplesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSamplesSuccess: (
        samples: Record<string, TraceSample>,
        payload?: any
    ) => {
        samples: Record<string, TraceSample>
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportCitationSamplesLogicMeta {
    key: string
}

export type reportCitationSamplesLogicType = MakeLogicType<
    reportCitationSamplesLogicValues,
    reportCitationSamplesLogicActions,
    ReportCitationSamplesLogicProps,
    reportCitationSamplesLogicMeta
>

/** The input, output and person of each trace a report cites, for its example rows. */
export const reportCitationSamplesLogic = kea<reportCitationSamplesLogicType>([
    path((key) => ['products', 'ai_observability', 'frontend', 'evaluations', 'reportCitationSamplesLogic', key]),
    props({} as ReportCitationSamplesLogicProps),
    key((props) => props.runId),
    connect(() => ({ values: [teamLogic, ['currentTeamId']] })),
    loaders(({ props, values }) => ({
        samples: [
            null as Record<string, TraceSample> | null,
            {
                loadSamples: async () =>
                    await fetchTraceSamples(String(values.currentTeamId), props.traceIds, {
                        earliest: props.earliest,
                        latest: props.latest,
                    }),
            },
        ],
    })),
    afterMount(({ actions }) => actions.loadSamples()),
])
